import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-backup', 'backup@corp.internal', 'service', 'sk-backup-a1b2c3d4', 'ops')")
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent arbitrary column access
    allowed_fields = ['department', 'role', 'username', 'email']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with field validation (field is from allowed list)
    # but value is user-controlled and concatenated directly
    query = f"SELECT username, email, department, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        actor = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute("INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
                   ('search', actor, f"{field}={value}"))
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<username>/profile', methods=['GET'])
def get_profile(username):
    """Get user profile. API key is only shown to the user themselves."""
    db = get_db()
    requester = request.headers.get('X-Authenticated-User', 'anonymous')

    if requester == username:
        row = db.execute("SELECT username, email, department, role, api_key FROM users WHERE username = ?", (username,)).fetchone()
    else:
        row = db.execute("SELECT username, email, department, role FROM users WHERE username = ?", (username,)).fetchone()

    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
